import { MakeLogicType, actions, kea, path, reducers, selectors } from 'kea'

import type { VisualizationArtifactAction } from '../types/artifactActionTypes'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface artifactActionsLogicValues {
    providers: Record<string, VisualizationArtifactAction>
    visualizationActions: VisualizationArtifactAction[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface artifactActionsLogicActions {
    deregisterArtifactAction: (providerId: string) => {
        providerId: string
    }
    registerArtifactAction: (
        providerId: string,
        action: VisualizationArtifactAction
    ) => {
        action: VisualizationArtifactAction
        providerId: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface artifactActionsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        visualizationActions: (providers: Record<string, VisualizationArtifactAction>) => VisualizationArtifactAction[]
    }
}

export type artifactActionsLogicType = MakeLogicType<
    artifactActionsLogicValues,
    artifactActionsLogicActions,
    Record<string, any>,
    artifactActionsLogicMeta
>

/**
 * Global, unkeyed store of the actions a host offers on the thread's visualization cards, the
 * mirror image of `attachedContextLogic`: context goes into the run, an artifact action takes a
 * result back out. A host (a mounted scene, or a kea logic registering through `cache.disposables`)
 * owns a stable `providerId` and upserts its action, so registration and removal stay symmetric.
 *
 * The action runs in the browser, which is what separates it from the agent writing the result back
 * over MCP: no round trip, no approval prompt, and the user decides per result.
 */
export const artifactActionsLogic = kea<artifactActionsLogicType>([
    path(['products', 'posthog_ai', 'frontend', 'logics', 'artifactActionsLogic']),

    actions({
        /** Idempotent upsert — re-register the same `providerId` to replace its action. */
        registerArtifactAction: (providerId: string, action: VisualizationArtifactAction) => ({ providerId, action }),
        deregisterArtifactAction: (providerId: string) => ({ providerId }),
    }),

    reducers({
        providers: [
            {} as Record<string, VisualizationArtifactAction>,
            {
                registerArtifactAction: (state, { providerId, action }) => ({ ...state, [providerId]: action }),
                deregisterArtifactAction: (state, { providerId }) => {
                    if (!(providerId in state)) {
                        return state
                    }
                    const { [providerId]: _dropped, ...rest } = state
                    return rest
                },
            },
        ],
    }),

    selectors({
        // Flattened across providers, deduped by action id (first writer wins) so a card never
        // renders two buttons with the same React key.
        visualizationActions: [
            (s) => [s.providers],
            (providers: Record<string, VisualizationArtifactAction>): VisualizationArtifactAction[] => {
                const seen = new Set<string>()
                const out: VisualizationArtifactAction[] = []
                for (const action of Object.values(providers)) {
                    if (seen.has(action.id)) {
                        continue
                    }
                    seen.add(action.id)
                    out.push(action)
                }
                return out
            },
        ],
    }),
])
